  "leetgpuId": 99,
  "title": "Grouped GEMM（分组矩阵乘法）",
  "titleEn": "Grouped GEMM",
  "titleZh": "分组矩阵乘法",
  "description": "使用 CUDA tiled GEMM 为连续行组选择各自权重矩阵",
  "problemId": "grouped-gemm",
